@Override
public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
    // Collect all vertices from the result map
    List<V> vertices = new ArrayList<>(resultMap.values());
    int total = vertices.size();
    if (total < 2) {
        // Not enough vertices to form a bipartite graph
        return;
    }

    // Split vertices into two partitions: left and right
    int mid = total / 2;
    List<V> left = vertices.subList(0, mid);
    List<V> right = vertices.subList(mid, total);

    // Add all vertices to the target graph
    for (V v : vertices) {
        target.addVertex(v);
    }

    // Add edges between every pair of vertices from left and right partitions
    for (V vLeft : left) {
        for (V vRight : right) {
            target.addEdge(vLeft, vRight);
        }
    }
}

